#include <torch/extension.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "kernel_operator.h"
#include "lib/matmul_intf.h"
#include "acl/acl.h"
#include <cstring>

using namespace AscendC;

constexpr MatmulApiStaticTiling DYNAMIC_TILING = {
    .usedCoreNum = -1, .M = -1, .N = -1, .Ka = -1, .Kb = -1,
    .singleCoreM = -1, .singleCoreN = -1, .singleCoreK = -1,
    .baseM = 128, .baseN = 128, .baseK = 64,
    .depthA1 = -1, .depthB1 = -1, .stepM = -1, .stepN = -1,
    .isBias = 0, .transLength = -1, .iterateOrder = -1,
    .shareMode = -1, .shareL1Size = -1, .shareL0CSize = -1, .shareUbSize = -1,
    .stepKa = -1, .stepKb = -1, .depthAL1CacheUB = -1, .depthBL1CacheUB = -1,
    .dbL0A = -1, .dbL0B = -1, .dbL0C = 1,
    .ALayoutInfoB = -1, .ALayoutInfoS = -1, .ALayoutInfoN = -1, .ALayoutInfoG = -1, .ALayoutInfoD = -1,
    .BLayoutInfoB = -1, .BLayoutInfoS = -1, .BLayoutInfoN = -1, .BLayoutInfoG = -1, .BLayoutInfoD = -1,
    .CLayoutInfoB = -1, .CLayoutInfoS1 = -1, .CLayoutInfoN = -1, .CLayoutInfoG = -1, .CLayoutInfoS2 = -1,
    .BatchNum = -1, .mxTypePara = -1, .cfg = CFG_NORM
};

class KernelMatmul {
public:
    using A_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
    using B_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
    using C_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
    using BIAS_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;

    AscendC::Matmul<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, DYNAMIC_TILING> mm;
    GlobalTensor<half> gmA;
    GlobalTensor<half> gmB;
    GlobalTensor<half> gmC;
    TPipe pipe;

    __aicore__ inline KernelMatmul() {}

    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tilingGM) {
        gmA.SetGlobalBuffer((__gm__ half*)a);
        gmB.SetGlobalBuffer((__gm__ half*)b);
        gmC.SetGlobalBuffer((__gm__ half*)c);
        mm.Init(reinterpret_cast<__gm__ TCubeTiling*>(tilingGM), &pipe);
        mm.SetTensorA(gmA);
        mm.SetTensorB(gmB);
    }

    __aicore__ inline void Process() {
        mm.IterateAll(gmC);
    }
};

extern "C" __global__ __aicore__ void matmul_custom(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tilingGM) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIC_ONLY);
    KernelMatmul kernel;
    kernel.Init(a, b, c, tilingGM);
    kernel.Process();
}

namespace cpp_extension_acs {

at::Tensor ascendc_matmul(const at::Tensor &a, const at::Tensor &b) {
    TORCH_CHECK(a.dtype() == torch::kHalf, "Input a must be half type");
    TORCH_CHECK(b.dtype() == torch::kHalf, "Input b must be half type");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "Only support 2D matmul");
    TORCH_CHECK(a.size(1) == b.size(0), "Matrix shape mismatch");
    TORCH_CHECK(a.device().is_privateuseone(), "Input must be on NPU");

    int32_t M = a.size(0);
    int32_t N = b.size(1);
    int32_t K = a.size(1);

    auto output = at::empty({M, N}, a.options());

    constexpr int32_t baseM = 128;
    constexpr int32_t baseN = 128;
    constexpr int32_t baseK = 64;

    int32_t singleCoreM = (M + baseM - 1) / baseM * baseM;
    int32_t singleCoreN = (N + baseN - 1) / baseN * baseN;
    int32_t singleCoreK = (K + baseK - 1) / baseK * baseK;
    if (singleCoreM == 0) singleCoreM = baseM;
    if (singleCoreN == 0) singleCoreN = baseN;
    if (singleCoreK == 0) singleCoreK = baseK;

    int32_t coreM = (M + singleCoreM - 1) / singleCoreM;
    int32_t coreN = (N + singleCoreN - 1) / singleCoreN;
    int32_t usedCoreNum = coreM * coreN;
    if (usedCoreNum > 8) usedCoreNum = 8;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int32_t stepM = singleCoreM / baseM;
    int32_t stepN = singleCoreN / baseN;
    int32_t stepKa = (singleCoreK + baseK - 1) / baseK;
    int32_t stepKb = stepKa;
    int32_t depthA1 = stepM * stepKa;
    int32_t depthB1 = stepN * stepKb;

    TCubeTiling tiling;
    memset(&tiling, 0, sizeof(TCubeTiling));
    tiling.usedCoreNum = usedCoreNum;
    tiling.M = M;
    tiling.N = N;
    tiling.Ka = K;
    tiling.Kb = K;
    tiling.singleCoreM = singleCoreM;
    tiling.singleCoreN = singleCoreN;
    tiling.singleCoreK = singleCoreK;
    tiling.baseM = baseM;
    tiling.baseN = baseN;
    tiling.baseK = baseK;
    tiling.depthA1 = depthA1;
    tiling.depthB1 = depthB1;
    tiling.stepM = stepM;
    tiling.stepN = stepN;
    tiling.isBias = 0;
    tiling.iterateOrder = 0;
    tiling.shareL0CSize = baseM * baseN;
    tiling.stepKa = stepKa;
    tiling.stepKb = stepKb;
    tiling.dbL0C = 1;

    size_t tilingSize = sizeof(TCubeTiling);
    void* tilingDevice = nullptr;
    aclrtMalloc(&tilingDevice, tilingSize, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMemcpy(tilingDevice, tilingSize, &tiling, tilingSize, ACL_MEMCPY_HOST_TO_DEVICE);

    auto acl_stream = c10_npu::getCurrentNPUStream().stream(true);
    matmul_custom<<<(uint32_t)usedCoreNum, nullptr, acl_stream>>>(
        (uint8_t*)(const_cast<void*>(a.storage().data())),
        (uint8_t*)(const_cast<void*>(b.storage().data())),
        (uint8_t*)(output.storage().data()),
        (uint8_t*)tilingDevice);

    aclrtFree(tilingDevice);
    return output;
}

}

at::Tensor matmul_impl_meta(const at::Tensor &a, const at::Tensor &b) {
    return at::empty({a.size(0), b.size(1)}, a.options());
}

TORCH_LIBRARY_FRAGMENT(cpp_extension_acs, m) {
    m.def("ascendc_matmul(Tensor a, Tensor b) -> Tensor");
}
TORCH_LIBRARY_IMPL(cpp_extension_acs, PrivateUse1, m) {
    m.impl("ascendc_matmul", TORCH_FN(cpp_extension_acs::ascendc_matmul));
}
TORCH_LIBRARY_IMPL(cpp_extension_acs, Meta, m) {
    m.impl("ascendc_matmul", &matmul_impl_meta);
}

import torch
import torch_npu

def run(a, b):
    return torch.ops.cpp_extension_acs.ascendc_matmul(a, b)
